<?php

namespace Database\Seeders;

use App\Enums\EmployeeStatus;
use App\Enums\OrganizationType;
use App\Models\Department;
use App\Models\Employee;
use App\Models\Organization;
use App\Models\OrganizationItResponsible;
use App\Models\User;
use App\Models\UserOrganizationAccess;
use App\Support\Permissions\Roles;
use Illuminate\Database\Seeder;
use RuntimeException;

/**
 * Development/demo data only — DatabaseSeeder never calls this in staging or production.
 * Idempotent: everything is matched by code / personnel number / username.
 * All demo accounts use DEMO_PASSWORD (generated by scripts/init-env.sh).
 */
class DemoSeeder extends Seeder
{
    /** code => [name, type, parent code] */
    private const ORGANIZATIONS = [
        'DEMO-HQ' => ['"Urganchtransgaz" MCHJ markaziy apparati (demo)', OrganizationType::HeadOffice, null],
        'DEMO-MGQB' => ['Urganch magistral gaz quvurlari boshqarmasi (demo)', OrganizationType::Subsidiary, 'DEMO-HQ'],
        'DEMO-GTS' => ['Xorazm gaz taqsimlash shoxobchasi (demo)', OrganizationType::Subsidiary, 'DEMO-HQ'],
        'DEMO-XIVA' => ['Xiva tuman filiali (demo)', OrganizationType::Branch, 'DEMO-GTS'],
    ];

    private const DEPARTMENTS = [
        'AT' => 'Axborot texnologiyalari bo\'limi',
        'BUX' => 'Buxgalteriya',
        'KAD' => 'Kadrlar bo\'limi',
    ];

    private const LAST_NAMES = ['Karimov', 'Gʻulomov', 'Rahimova', 'Toʻxtayev', 'Yusupov', 'Abdullayeva', 'Qodirov', 'Ergasheva', 'Oʻrozov', 'Sobirov'];

    private const FIRST_NAMES = ['Aziz', 'Bekzod', 'Dilnoza', 'Jasur', 'Shahlo', 'Rustam', 'Malika', 'Sherzod', 'Nodira', 'Ulugʻbek'];

    private const POSITIONS = ['Muhandis-dasturchi', 'Tizim administratori', 'Bosh mutaxassis', 'Buxgalter', 'Operator', 'Tarmoq muhandisi'];

    public function run(): void
    {
        $password = config('app.demo_password');
        if (! is_string($password) || $password === '') {
            throw new RuntimeException('DEMO_PASSWORD is empty: run ./scripts/init-env.sh or set it in .env before seeding demo data.');
        }

        $organizations = $this->organizations();
        $employees = $this->departmentsAndEmployees($organizations);
        $this->users($organizations, $employees, $password);
        $this->itResponsibles($organizations, $employees);
    }

    /** @return array<string, Organization> */
    private function organizations(): array
    {
        $result = [];
        foreach (self::ORGANIZATIONS as $code => [$name, $type, $parent]) {
            $result[$code] = Organization::withoutGlobalScopes()->firstOrCreate(
                ['code' => $code],
                ['name' => $name, 'type' => $type, 'parent_id' => $parent ? $result[$parent]->id : null, 'is_active' => true],
            );
        }

        return $result;
    }

    /**
     * @param  array<string, Organization>  $organizations
     * @return array<string, list<Employee>>
     */
    private function departmentsAndEmployees(array $organizations): array
    {
        $result = [];
        $n = 0;
        foreach ($organizations as $code => $organization) {
            $departments = [];
            foreach (self::DEPARTMENTS as $departmentCode => $departmentName) {
                $departments[] = Department::withoutGlobalScopes()->firstOrCreate(
                    ['organization_id' => $organization->id, 'code' => $departmentCode],
                    ['name' => $departmentName, 'is_active' => true],
                );
            }

            $result[$code] = [];
            for ($i = 0; $i < 8; $i++, $n++) {
                $result[$code][] = Employee::withoutGlobalScopes()->firstOrCreate(
                    ['organization_id' => $organization->id, 'personnel_number' => sprintf('D%04d', $n + 1)],
                    [
                        'department_id' => $departments[$i % count($departments)]->id,
                        'last_name' => self::LAST_NAMES[$n % count(self::LAST_NAMES)],
                        'first_name' => self::FIRST_NAMES[($n * 3) % count(self::FIRST_NAMES)],
                        'position' => self::POSITIONS[$n % count(self::POSITIONS)],
                        'phone' => sprintf('+99891%07d', 4000000 + $n),
                        'status' => $i === 7 ? EmployeeStatus::OnLeave : EmployeeStatus::Active,
                        'hired_at' => now()->subYears(1 + $n % 9)->toDateString(),
                    ],
                );
            }
        }

        return $result;
    }

    /**
     * @param  array<string, Organization>  $organizations
     * @param  array<string, list<Employee>>  $employees
     */
    private function users(array $organizations, array $employees, string $password): void
    {
        foreach ($this->accounts() as $username => [$role, $orgCode, $descendants, $employeeIndex]) {
            $employee = $orgCode !== null && $employeeIndex !== null ? $employees[$orgCode][$employeeIndex] : null;
            $existing = User::withoutGlobalScopes()->withTrashed()->where('username', $username)->first();
            if ($existing !== null) {
                continue;
            }

            $user = User::create([
                'username' => $username,
                'name' => $employee !== null ? $employee->full_name : 'Demo '.$role,
                'email' => $username.'@demo.at.urtg.uz',
                'organization_id' => $orgCode !== null ? $organizations[$orgCode]->id : null,
                'employee_id' => $employee?->id,
                'password' => $password,
                'must_change_password' => false,
                'password_changed_at' => now(),
            ]);
            $user->assignRole($role);

            if ($orgCode !== null) {
                UserOrganizationAccess::create([
                    'user_id' => $user->id,
                    'organization_id' => $organizations[$orgCode]->id,
                    'include_descendants' => $descendants,
                ]);
            }
        }
    }

    /**
     * One demo account per role: username => [role, organization code, access incl. descendants, employee index].
     *
     * @return array<string, array{0: string, 1: string|null, 2: bool, 3: int|null}>
     */
    private function accounts(): array
    {
        return [
            'demo.super' => [Roles::SUPER_ADMIN, null, false, null],
            'demo.head' => [Roles::CENTRAL_IT_HEAD, 'DEMO-HQ', true, 0],
            'demo.staff' => [Roles::CENTRAL_IT_STAFF, 'DEMO-HQ', true, 1],
            'demo.itresp' => [Roles::ORG_IT_RESPONSIBLE, 'DEMO-GTS', true, 0],
            'demo.orghead' => [Roles::ORG_HEAD, 'DEMO-GTS', true, 1],
            'demo.employee' => [Roles::EMPLOYEE, 'DEMO-GTS', false, 2],
            'demo.accountant' => [Roles::ACCOUNTANT, 'DEMO-MGQB', false, 3],
            'demo.auditor' => [Roles::AUDITOR, 'DEMO-HQ', true, null],
        ];
    }

    /**
     * @param  array<string, Organization>  $organizations
     * @param  array<string, list<Employee>>  $employees
     */
    private function itResponsibles(array $organizations, array $employees): void
    {
        foreach (['DEMO-GTS' => 0, 'DEMO-MGQB' => 4] as $code => $index) {
            OrganizationItResponsible::withoutGlobalScopes()->firstOrCreate(
                ['organization_id' => $organizations[$code]->id, 'employee_id' => $employees[$code][$index]->id],
                ['is_primary' => true, 'assigned_at' => now()->toDateString()],
            );
        }
    }
}
